# Scored file: sign_or_verify_key.py\n# Demonstrate AWS KMS digital signatures (signing with RSA/HMAC or verification)\n\nimport os\nimport json\nimport boto3\nfrom botocore.exceptions import ClientError\n\nfrom security_client import get_kms_client\nfrom security_models import PlaintextPayload, SignatureResult\n\ndef sign(payload: str, key_id: str = None, algorithm: str = 'RSAES_PKCS1_V1_5') -> SignatureResult:\n    \"\"\"Sign a plaintext payload using AWS KMS.\n\n    Returns a dict with the Base64‑encoded signature.\n    \"\"\"\n    client = get_kms_client()\n    # Allow caller to override the KMS key (default is env var)\n    if not key_id:\n        key_id = os.getenv('AWS_KMS_KEY_ID')\n        if not key_id:\n            raise RuntimeError('AWS_KMS_KEY_ID environment variable not set')\n\n    try:\n        resp = client.sign(\n            KeyId=key_id,\n            Message=payload.encode('utf-8'),\n            MessageType='DIGEST',  # KMS expects a hash; caller must hash first if needed\n            SigningAlgorithm=algorithm\n        )\n        return SignatureResult(signature=resp['Signature'])\n    except ClientError as e:\n        raise RuntimeError(f\"KMS signing error: {e}\") from e\n\ndef verify(signature: bytes, payload: str, key_id: str = None, algorithm: str = 'RSAES_PKCS1_V1_5') -> bool:\n    \"\"\"Verify a signature produced by KMS.\n\n    Returns True if verification succeeds, False otherwise.\n    \"\"\"\n    client = get_kms_client()\n    if not key_id:\n        key_id = os.getenv('AWS_KMS_KEY_ID')\n        if not key_id:\n            raise RuntimeError('AWS_KMS_KEY_ID environment variable not set')\n\n    try:\n        resp = client.verify(\n            KeyId=key_id,\n            Message=payload.encode('utf-8'),\n            Signature=signature,\n            MessageType='DIGEST',  # payload must be a hash\n            SigningAlgorithm=algorithm\n        )\n        return resp['SignatureValid']\n    except ClientError as e:\n        raise RuntimeError(f\"KMS verification error: {e}\") from e\n\nif __name__ == \"__main__\":\n    msg = \"Example message to sign.\"\n    sig = sign(msg)\n    print(f\"Signature: {sig.signature}\")\n    # Verify the same message\n    ok = verify(sig.signature, msg)\n    print('Verification OK?' , ok)\n